<?php
require_once __DIR__.'/includes/bootstrap.php';
if(is_logged_in()) redirect('dashboard.php');
$error='';
if($_SERVER['REQUEST_METHOD']==='POST'){ verify_csrf(); $email=trim($_POST['email']??''); $pass=$_POST['password']??'';
  $st=$pdo->prepare("SELECT id,name,email,password_hash,role FROM users WHERE email=? AND active=1 LIMIT 1"); $st->execute([$email]); $u=$st->fetch();
  if($u && password_verify($pass,$u['password_hash'])){ session_regenerate_id(true); $_SESSION['user_id']=$u['id'];$_SESSION['user_name']=$u['name'];$_SESSION['user_role']=$u['role']; flash('Welcome back, '.$u['name'].'.'); redirect('dashboard.php'); }
  $error='Invalid email or password.';
}
